import { registerScript, ABrain, LanguageMgr, Point } from "../../runtime.js";

export class FourTerrorFrantCattleBoss extends ABrain {
  m_attackTurn = 0;
  m_pointMakeDamage = null;
  m_isBorn = false;
  m_targer = null;
  OnBeginSelfTurn() {
            super.OnBeginSelfTurn();
        }
  OnBeginNewTurn() {
            super.OnBeginNewTurn();
            this.m_body.CurrentDamagePlus = 1;
            this.m_body.CurrentShootMinus = 1;
        }
  OnCreated() {
            super.OnCreated();
            this.m_isBorn = false;
        }
  OnStartAttacking() {
            super.OnStartAttacking();

            this.m_attackTurn++;
            switch (this.m_attackTurn)
            {
                case 1:

                    //if (!m_isBorn)
                    //{
                    //((PVEGame)Game).SendLivingActionMapping(Body, "stand", "stand");
                    //Body.PlayMovie("born", 1000, 0);
                    //Body.Say("<span class=\"red\">Estou realmente com raiva. Vou esmagar todos!</span>", 0, 1200);
                    this.Body.CallFuction(this.JumpAttack.bind(this), 4000);
                    //m_isBorn = true;
                    //}
                    //else
                    //{
                    //Body.CallFuction(RunAttack, 1000);
                    //}
                    break;
                case 10:
                    this.Body.CallFuction(this.JumpAttack.bind(this), 1000);
                    this.m_attackTurn = 0;
                    break;
                default:
                    this.Body.CallFuction(this.RunAttack.bind(this), 1000);
                    break;
            }
        }
  JumpAttack() {
            this.m_targer = this.Game.FindRandomPlayer();
            if (this.m_targer != null)
            {
                let randAttack = this.Game.Random.Next(100);
                this.Body.PlayMovie("jump", 1000, 0);
                this.Body.BoltMove(this.m_targer.X, this.m_targer.Y, 3000);
                ((this.Game)).SendObjectFocus(this.m_targer, 1, 3000, 0);
                if (randAttack < 50)
                {
                    this.Body.CurrentDamagePlus = 1.5;
                    this.Body.PlayMovie("fallB", 4000, 0);
                }
                else
                {
                    this.Body.PlayMovie("fall", 4000, 0);
                }
                this.Body.RangeAttacking(this.m_targer.X - 50, this.m_targer.X + 50, "cry", 5000, true);
            }
        }
  RunAttack() {
            this.m_targer = this.Game.FindFarPlayer(this.Body.X, this.Body.Y);
            if (this.m_targer != null)
            {
                this.Body.ChangeDirection(this.m_targer, 100);

                if (this.m_targer.X + 200 >= this.Game.Map.Info.DeadWidth || this.m_targer.X - 200 <= 0)
                {
                    this.Body.CallFuction(this.JumpAttack.bind(this), 1000);
                }
                // check it's current
                else if (this.Body.Distance(this.m_targer.X, this.m_targer.Y) <= 100)
                {
                    this.Body.CallFuction(this.NearAttack.bind(this), 1000);
                }
                else
                {
                    this.Body.CallFuction(this.MoveAndAttack.bind(this), 500);
                }
            }
        }
  MoveAndAttack() {
            this.m_pointMakeDamage = new Point(this.Body.X, this.Body.Y);
            if (this.Body.Direction == -1)
                this.Body.MoveTo(this.m_targer.X - 100, this.m_targer.Y, "walk", 1000, this.AttackRangeRun.bind(this), 12);
            else
                this.Body.MoveTo(this.m_targer.X + 100, this.m_targer.Y, "walk", 1000, this.AttackRangeRun.bind(this), 12);
        }
  NearAttack() {
            this.m_pointMakeDamage = new Point(this.Body.X, this.Body.Y);
            if (this.Body.Direction == -1)
            {
                this.Body.MoveTo(this.m_targer.X - 200, this.m_targer.Y, "walk", 500, this.AttackRangeRun.bind(this), 12);
            }
            else
            {
                this.Body.MoveTo(this.m_targer.X + 200, this.m_targer.Y, "walk", 500, this.AttackRangeRun.bind(this), 12);
            }
        }
  AttackRangeRun() {
            this.Body.ChangeDirection(this.m_targer, 100);
            if (this.Body.X < this.m_pointMakeDamage.X)
            {
                this.Body.RangeAttacking(this.Body.X, this.m_pointMakeDamage.X, "cry", 0, true);
            }
            else
            {
                this.Body.RangeAttacking(this.m_pointMakeDamage.X, this.Body.X, "cry", 0, true);
            }
        }
  OnDie() {            
            super.OnDie();
            this.Body.Say(LanguageMgr.GetTranslation("GameServerScript.AI.NPC.FourTerrorFrantCattleBoss.msg2"), 0, 1200);
        }
  OnStopAttacking() {
            super.OnStopAttacking();
        }
}
